svg.script:
const W = [[30.0, 36.02], [66.02, 70.62], [100.62, 103.14], [133.14, 136.03], [166.03, 169.15], [199.15, 202.35]], C = 202.35, D = 25;
document.documentElement.addEventListener('click', () => {
  const as = document.getAnimations().filter(a => a instanceof CSSAnimation);
  if (!as.length) return;
  const t = ((as[0].currentTime / 1000 + D) % C + C) % C;
  if (W.some(([a, b]) => a <= t && t < b)) return;
  const s = (W.find(([a]) => a > t) || W[0])[0] - 0.05;
  as.forEach(a => { a.currentTime = (((s - D) % C + C) % C) * 1000; });
});
